import{_ as a,o as t,c as i,ae as l}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"CRUD Actions, Real-Time Updates, and Tests","description":"","frontmatter":{"work_package_id":"WP02","title":"CRUD Actions, Real-Time Updates, and Tests","lane":"done","dependencies":["WP01"],"base_branch":"017-lane-list-and-status-display-WP01","base_commit":"c87845d6c6938059f4f9500d33801e971be90a5b","created_at":"2026-03-01T13:32:45.065445+00:00","subtasks":["T006","T007","T008","T009","T010","T011"],"phase":"Phase 2 - Interaction and Hardening","assignee":"","agent":"claude-haiku","shell_pid":"68186","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/017-lane-list-and-status-display/tasks/WP02-crud-actions-and-realtime-updates.md","filePath":"specs/017-lane-list-and-status-display/tasks/WP02-crud-actions-and-realtime-updates.md"}'),s={name:"specs/017-lane-list-and-status-display/tasks/WP02-crud-actions-and-realtime-updates.md"};function n(o,e,r,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="work-package-prompt-wp02-crud-actions-real-time-updates-and-tests" tabindex="-1">Work Package Prompt: WP02 - CRUD Actions, Real-Time Updates, and Tests <a class="header-anchor" href="#work-package-prompt-wp02-crud-actions-real-time-updates-and-tests" aria-label="Permalink to &quot;Work Package Prompt: WP02 - CRUD Actions, Real-Time Updates, and Tests&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement lane CRUD actions (create, attach, detach, cleanup) accessible from the panel.</li><li>Implement confirmation dialog for destructive actions.</li><li>Implement real-time status badge updates via bus event subscription.</li><li>Integrate orphan detection flags and stale-status indicators.</li><li>Deliver Playwright tests and performance benchmarks.</li></ul><p>Success criteria:</p><ul><li>Lane create/attach/detach/cleanup actions execute successfully from the panel.</li><li>Cleanup requires confirmation dialog before execution; no cleanup without confirmation.</li><li>Status badges update within 1 second of bus events.</li><li>Orphaned lanes display a distinct visual indicator.</li><li>Bus connectivity loss shows &quot;status may be stale&quot; indicator.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/017-lane-list-and-status-display/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/017-lane-list-and-status-display/spec.md</code></li><li>Lane panel: <code>apps/desktop/src/panels/</code> (WP01)</li><li>Lane lifecycle API: spec 008</li><li>Orphan detection: spec 015</li><li>Internal event bus: <code>apps/runtime/src/protocol/bus.ts</code> (spec 001)</li></ul><p>Constraints:</p><ul><li>Cleanup requires confirmation (FR-017-004).</li><li>Updates must not block main UI thread.</li><li>Keep files under 500 lines.</li><li>TypeScript + Bun + ElectroBun.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t006-implement-lane-action-handlers" tabindex="-1">Subtask T006 - Implement lane action handlers <a class="header-anchor" href="#subtask-t006-implement-lane-action-handlers" aria-label="Permalink to &quot;Subtask T006 - Implement lane action handlers&quot;">​</a></h3><ul><li>Purpose: enable lane management operations from the panel UI.</li><li>Steps: <ol><li>Implement <code>LaneActions</code> in <code>apps/desktop/src/panels/lane_actions.ts</code>: a. <code>createLane(workspaceId)</code>: call runtime API to create a new lane with default name. Update panel on success. b. <code>attachLane(laneId)</code>: call runtime API to attach to the lane. Trigger context switch to the attached lane. Update all tabs (spec 016 integration). c. <code>detachLane(laneId)</code>: call runtime API to detach from the lane. Clear active context if this was the active lane. d. <code>cleanupLane(laneId)</code>: show confirmation dialog (T007). On confirm, call runtime API to clean up. On decline, do nothing.</li><li>Implement error handling: a. Display inline error message in the panel if an action fails. b. Log error details for debugging. c. Auto-dismiss error after 10 seconds or on user action.</li><li>Implement optimistic UI: a. On create: immediately add a &quot;provisioning&quot; lane to the list before API response. b. On attach: immediately highlight the lane before API confirmation. c. On failure: revert optimistic update and show error.</li><li>Wire actions into <code>LaneListItem</code> click/menu handlers and keyboard navigation.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/lane_actions.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: create lane, verify provisioning item appears, then confirm via API mock.</li><li>Unit test: attach lane, verify context switch triggered.</li><li>Unit test: cleanup lane without confirmation, verify action NOT executed.</li><li>Unit test: action failure, verify error message displayed and optimistic update reverted.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t007-implement-confirmation-dialog" tabindex="-1">Subtask T007 - Implement confirmation dialog <a class="header-anchor" href="#subtask-t007-implement-confirmation-dialog" aria-label="Permalink to &quot;Subtask T007 - Implement confirmation dialog&quot;">​</a></h3><ul><li>Purpose: require explicit user confirmation before destructive actions (cleanup).</li><li>Steps: <ol><li>Implement <code>ConfirmationDialog</code> in <code>apps/desktop/src/panels/confirmation_dialog.ts</code>: a. Accept: title, message, confirm label, cancel label, and callback. b. Display modal dialog with clear warning about the action&#39;s consequences. c. For cleanup: include lane name, current state, and resource details. d. Confirm button calls the action callback; cancel dismisses the dialog.</li><li>Implement keyboard accessibility: a. Escape dismisses the dialog. b. Enter confirms the action. c. Tab moves between confirm and cancel buttons. d. Focus is trapped within the dialog while open.</li><li>Implement dialog animation: brief fade-in to avoid jarring appearance.</li><li>FR-017-004: cleanup actions require user confirmation.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/confirmation_dialog.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: open dialog, press confirm, verify callback called.</li><li>Unit test: open dialog, press cancel, verify callback NOT called.</li><li>Unit test: press Escape, verify dialog dismissed.</li><li>Unit test: verify focus trap within dialog.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-implement-real-time-bus-event-subscription" tabindex="-1">Subtask T008 - Implement real-time bus event subscription <a class="header-anchor" href="#subtask-t008-implement-real-time-bus-event-subscription" aria-label="Permalink to &quot;Subtask T008 - Implement real-time bus event subscription&quot;">​</a></h3><ul><li>Purpose: update lane status badges in real time based on lifecycle events.</li><li>Steps: <ol><li>Implement <code>LaneEventHandler</code> in <code>apps/desktop/src/panels/lane_event_handler.ts</code>: a. Subscribe to lane lifecycle events on the internal bus: i. <code>lane.state.changed</code>: update the badge for the affected lane. ii. <code>lane.created</code>: add a new lane to the list. iii. <code>lane.cleaned_up</code> / <code>lane.closed</code>: remove the lane from the list or show closed badge. b. On each event, update the corresponding <code>LaneListItem</code> in the panel.</li><li>Implement debouncing: a. If rapid state transitions arrive for the same lane, only render the final state. b. Use <code>requestAnimationFrame</code> batching to avoid excessive re-renders.</li><li>Implement event ordering: a. Process events in sequence number order if available. b. Discard out-of-order events that would revert to a previous state.</li><li>Wire event handler into the lane panel lifecycle (subscribe on mount, unsubscribe on unmount).</li><li>FR-017-005: update lane status badges in real time via bus events.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/lane_event_handler.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: emit state change event, verify badge updates.</li><li>Unit test: emit lane.created, verify new lane appears.</li><li>Unit test: emit lane.cleaned_up, verify lane removed/closed.</li><li>Unit test: rapid events for same lane, verify only final state rendered.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-implement-orphan-detection-integration" tabindex="-1">Subtask T009 - Implement orphan detection integration <a class="header-anchor" href="#subtask-t009-implement-orphan-detection-integration" aria-label="Permalink to &quot;Subtask T009 - Implement orphan detection integration&quot;">​</a></h3><ul><li>Purpose: flag orphaned lanes with a distinct visual indicator in the panel.</li><li>Steps: <ol><li>Query spec 015 orphan detection API for the list of orphaned lanes: a. On panel mount and after each detection cycle event, refresh the orphan list. b. Cross-reference orphan list with the lane list.</li><li>For each orphaned lane: a. Add an orphan flag to the <code>LaneListItem</code>. b. Display a distinct warning icon (orange triangle or similar) next to the status badge. c. Add &quot;Orphaned&quot; to the tooltip with remediation suggestion.</li><li>Subscribe to <code>orphan.detection.cycle_completed</code> events to refresh the orphan list.</li><li>FR-017-006: integrate with orphan detection to flag orphaned lanes.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/lane_event_handler.ts</code> (orphan subscription)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/lane_list_item.ts</code> (orphan display)</li></ul></li><li>Validation: <ul><li>Unit test: lane flagged as orphaned, verify warning icon displayed.</li><li>Unit test: lane orphan status cleared, verify warning icon removed.</li><li>Unit test: orphan detection cycle event, verify list refreshed.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t010-implement-stale-status-indicator" tabindex="-1">Subtask T010 - Implement stale-status indicator <a class="header-anchor" href="#subtask-t010-implement-stale-status-indicator" aria-label="Permalink to &quot;Subtask T010 - Implement stale-status indicator&quot;">​</a></h3><ul><li>Purpose: warn users when lane status may be outdated due to bus connectivity issues.</li><li>Steps: <ol><li>Monitor bus connectivity: a. If no bus events received for a configurable timeout (default: 30 seconds), display a banner. b. Banner text: &quot;Lane status may be stale. Bus connectivity issue detected.&quot;</li><li>Display the banner at the top of the lane panel, above the lane list.</li><li>Auto-dismiss the banner when bus events resume.</li><li>Implement visual distinction: use amber/yellow background to indicate warning without alarm.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/lane_event_handler.ts</code> (connectivity monitoring)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/panels/lane_panel.ts</code> (banner display)</li></ul></li><li>Validation: <ul><li>Unit test: simulate bus silence for 30s, verify stale banner displayed.</li><li>Unit test: resume events after stale, verify banner dismissed.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t011-add-playwright-end-to-end-tests-and-performance-benchmarks" tabindex="-1">Subtask T011 - Add Playwright end-to-end tests and performance benchmarks <a class="header-anchor" href="#subtask-t011-add-playwright-end-to-end-tests-and-performance-benchmarks" aria-label="Permalink to &quot;Subtask T011 - Add Playwright end-to-end tests and performance benchmarks&quot;">​</a></h3><ul><li>Purpose: validate the complete lane panel experience and performance SLOs.</li><li>Steps: <ol><li>Create <code>apps/desktop/tests/e2e/panels/lane_panel.test.ts</code>: a. Test: open app, verify lane panel visible with correct lanes. b. Test: create lane from panel, verify it appears in the list. c. Test: attach to a lane, verify context switch and tab updates. d. Test: cleanup lane, verify confirmation dialog, confirm, verify removed. e. Test: keyboard navigation through lane list.</li><li>Create <code>apps/desktop/tests/e2e/panels/lane_realtime.test.ts</code>: a. Test: emit state change event, verify badge updates within 1 second. b. Test: rapid state transitions, verify final state displayed. c. Test: lane added externally, verify appears in panel. d. Test: lane removed externally, verify removed from panel.</li><li>Create <code>apps/desktop/tests/e2e/panels/lane_performance.test.ts</code>: a. Render 50 lanes, measure initial paint time, assert &lt; 300ms. b. Emit 20 state change events, measure update latency, assert p95 &lt; 1s.</li><li>Capture screenshots for visual regression baseline.</li><li>Aim for &gt;=85% line coverage across panel modules.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/e2e/panels/lane_panel.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/e2e/panels/lane_realtime.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/e2e/panels/lane_performance.test.ts</code></li></ul></li><li>Parallel: Yes (after T006-T010 are integrated).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Playwright for UI interactions and real-time update verification.</li><li>Performance benchmarks for render and update latency SLOs.</li><li>Unit test coverage for action handlers and event processing.</li><li>Aim for &gt;=85% line coverage.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: bus event floods cause excessive re-renders.</li><li>Mitigation: requestAnimationFrame batching and debouncing.</li><li>Risk: optimistic UI creates confusion on failure.</li><li>Mitigation: clear revert with error message on action failure.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm cleanup action cannot execute without confirmation dialog.</li><li>Confirm real-time updates use debouncing and event ordering.</li><li>Confirm orphan flag integration refreshes on detection cycle events.</li><li>Confirm stale-status indicator appears on bus timeout and clears on resume.</li><li>Confirm Playwright tests verify all CRUD actions and real-time updates.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:32:45Z – claude-haiku – shell_pid=68186 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:34:08Z – claude-haiku – shell_pid=68186 – lane=done – Implemented</li></ul>',32)])])}const h=a(s,[["render",n]]);export{m as __pageData,h as default};
